#!/usr/bin/env bash
# Show the status of compression jobs running in tmux.
#
# Sessions: c<N> (movie), series<N> (series), a<N> (audio).
#
# New jobs write work/<session>.state and ffmpeg -progress output to
# work/<session>.progress. Jobs generated by older versions of the
# scripts have neither; for those the tmux pane history and the job
# script are parsed instead.
#
# Read-only: this script only reads the state / progress files, the
# job script, the job's item logs and the sources (ffprobe). It never
# writes, moves or signals anything a running job uses.
#
# Times shown per job (CURRENT: the item; JOB QUEUE, only for a job of
# more than one item: the whole job):
#   Item elapsed   since the current movie / episode attempt began (first
#                  pass / step after its item_begin, from the item log)
#   Item ETA       rest of the current encode: remaining runtime / speed
#   Total elapsed  since the whole job started (state "started")
#   Total ETA      current encode + the items still to come, estimated
#                  from the job's completed items (source seconds encoded
#                  per wall-clock second, overhead included); without a
#                  completed item, from the current encode speed.
#                  "Unknown" when there is nothing reliable to base it on.
set -u

WORK="$HOME/compress/work"
RECENT_HOURS=72
RULE="------------------------------------------------------------"

command -v tmux >/dev/null || {
    echo "tmux not found"
    exit 1
}

command -v ffprobe >/dev/null || {
    echo "ffprobe not found"
    exit 1
}

source "$WORK/lib/bitrate.sh"
source "$WORK/lib/media_probe.sh"
source "$WORK/lib/media_stats.sh"

job_type_for() {
    case "$1" in
        c[0-9]*)      echo "movie" ;;
        series[0-9]*) echo "series" ;;
        a[0-9]*)      echo "audio" ;;
        *)            echo "" ;;
    esac
}

# type_label TYPE  ->  "Movie" / "Series" / "Audio"
type_label() {
    case "$1" in
        movie)  echo "Movie" ;;
        series) echo "Series" ;;
        audio)  echo "Audio" ;;
        *)      echo "?" ;;
    esac
}

# item_word TYPE  ->  what one item of the job is called
item_word() {
    case "$1" in
        series) echo "Episode" ;;
        movie)  echo "Movie" ;;
        *)      echo "Item" ;;
    esac
}

# read_state FILE  ->  fills associative array ST
read_state() {
    local k v

    ST=()

    while IFS='=' read -r k v; do
        [[ -n "$k" ]] && ST["$k"]="$v"
    done < "$1"
}

# progress_values FILE  ->  "out_seconds speed progress"
progress_values() {
    tail -n 60 "$1" 2>/dev/null |
    awk -F'=' '
        $1 == "out_time_us" && $2 ~ /^[0-9]+$/ { t = $2 / 1000000 }
        $1 == "out_time_ms" && $2 ~ /^[0-9]+$/ && t == "" { t = $2 / 1000000 }
        $1 == "speed"    { s = $2; sub(/x$/, "", s); gsub(/ /, "", s) }
        $1 == "progress" { p = $2 }
        END {
            printf "%s %s %s\n",
                (t == "" ? "-" : sprintf("%.0f", t)),
                (s ~ /^[0-9.]+$/ ? s : "-"),
                (p == "" ? "-" : p)
        }'
}

# Unquote the first shell word of a line produced by printf %q.
first_word() {
    xargs -n 1 2>/dev/null <<< "$1" | head -n 1
}

# Paths passed to "ffmpeg -y -i" in an (old) job script, in order, unique.
script_inputs() {
    local line

    grep -E '^ *ffmpeg -y -i ' "$1" 2>/dev/null |
    while IFS= read -r line; do
        line="${line#*ffmpeg -y -i }"
        first_word "$line"
    done |
    awk '!seen[$0]++'
}

# script_item_inputs SCRIPT  ->  fills ITEM_IN[index]=input from the
# job script's item_begin lines (current job format; none for old ones)
script_item_inputs() {
    local line idx

    ITEM_IN=()
    [[ -f "$1" ]] || return 0

    while IFS= read -r line; do
        line="${line#*item_begin }"
        idx="${line%% *}"
        [[ "$idx" =~ ^[0-9]+$ && -z "${ITEM_IN[$idx]+x}" ]] || continue
        ITEM_IN[$idx]=$(first_word "${line#* }")
    done < <(grep -E '^[[:space:]]*(if[[:space:]]+)?item_begin [0-9]+ ' "$1" 2>/dev/null)
}

# duration_of PATH  ->  DUR_OUT = whole seconds of the source ("" when
# unknown); probed once per path and run
duration_of() {
    local p="${1:-}" d=""

    DUR_OUT=""
    [[ -n "$p" ]] || return 0

    if [[ -z "${DUR[$p]+x}" ]]; then
        [[ -f "$p" ]] && d=$(get_duration "$p" 2>/dev/null | head -n 1)
        if [[ "$d" =~ ^[0-9]+(\.[0-9]+)?$ ]]; then
            DUR[$p]=$(awk -v d="$d" 'BEGIN { printf "%.0f", d }')
        else
            DUR[$p]=""
        fi
    fi

    DUR_OUT="${DUR[$p]}"
}

# job_events LOG_DIR  ->  one line per pass / step the job started, in
# time order, tab separated:
#   EPOCH  ITEM  KIND (pass|step)  LABEL  OK  FIRST  CRF  INPUT
# from the "===== <date> <time>  pass|step <label>" headers of the item
# logs (item-<N>.log). OK: the ffmpeg run completed ("muxing overhead"
# summary). FIRST: the first pass / step after an item_begin ("input:"
# line), i.e. where the current attempt of that item began. CRF: the
# -crf:v:0 of the logged command (a CRF retry's actual value), "-" if none.
job_events() {
    local f out
    local -a files=()

    for f in "$1"/item-*.log; do
        [[ -f "$f" ]] && files+=("$f")
    done
    (( ${#files[@]} )) || return 0

    out=$(awk '
        function flush() {
            if (ts != "")
                printf "%s\t%s\t%s\t%s\t%d\t%d\t%s\t%s\n", ts, idx, kind, label, ok, first, crf, inp
            ts = ""
        }
        FNR == 1 {
            flush()
            idx = FILENAME; sub(/.*item-/, "", idx); sub(/\.log$/, "", idx)
            inp = ""; fresh = 0; cmd = 0
        }
        /^input:  / { flush(); inp = substr($0, 9); fresh = 1; next }
        /^===== [0-9-]+ [0-9:]+  (pass|step) / {
            flush()
            ts = $2 " " $3; kind = $4; label = $5
            ok = 0; first = fresh; fresh = 0; crf = "-"; cmd = 1
            next
        }
        cmd == 1 {
            cmd = 0
            if (match($0, /-crf:v:0 [0-9.]+/)) crf = substr($0, RSTART + 9, RLENGTH - 9)
        }
        ts != "" && /muxing overhead/ { ok = 1 }
        END { flush() }
    ' "${files[@]}" 2>/dev/null)

    [[ -n "$out" ]] || return 0

    # dates -> epoch in one date call; dropped entirely if any is unusable
    local epochs
    epochs=$(cut -f1 <<< "$out" | date -f - +%s 2>/dev/null) || return 0
    [[ $(wc -l <<< "$epochs") == $(wc -l <<< "$out") ]] || return 0

    paste <(printf '%s\n' "$epochs") <(cut -f2- <<< "$out") | sort -s -n -k1,1
}

# job_estimates NOW CUR SPEED ITEM_ETA
#
# For a job with a state file (ST) and its item logs: sets
#   R[item_elapsed]  current item attempt ("Unknown" when not found)
#   R[total_eta]     whole job ("Unknown" when it cannot be estimated)
#   R[total_basis]   what the total ETA is based on
#   R[crf]           the CRF of the current encode, when the log has it
#   ITEM_RUN_CRF[i]  the last encode CRF logged for item i (display only)
# CUR / SPEED / ITEM_ETA: current encode progress ("-" / "" = none).
job_estimates() {
    local now="$1" cur="$2" speed="$3" item_eta="$4"
    local item="${ST[item]:-0}" items="${ST[items]:-0}" pass="${ST[pass]:-}"
    local duration="${ST[duration]:-}" word
    local -a ev=() cs=() ci=() co=() cin=()
    local line ts idx kind label ok first crf inp n k end
    local item_start="" item_crf=""

    word=$(item_word "${ST[type]:-}")
    word="${word,,}"

    R[item_elapsed]="Unknown"
    R[total_eta]="Unknown"
    R[total_basis]=""
    ITEM_RUN_CRF=()

    [[ "$item" =~ ^[0-9]+$ ]] || item=0
    [[ "$items" =~ ^[0-9]+$ ]] || items=0

    [[ -n "${ST[log_dir]:-}" && -d "${ST[log_dir]}" ]] &&
        mapfile -t ev < <(job_events "${ST[log_dir]}")

    # encode cycles: consecutive encode passes of one item (a movie's CRF
    # retry / test belongs to its cycle; a series season retry pass starts
    # new cycles, one per episode)
    for line in "${ev[@]+"${ev[@]}"}"; do
        IFS=$'\t' read -r ts idx kind label ok first crf inp <<< "$line"

        if [[ "$idx" == "$item" ]]; then
            [[ "$first" == 1 ]] && item_start="$ts"
            [[ "$kind" == pass && "$label" == encode && "$crf" != "-" ]] && item_crf="$crf"
        fi

        # each item's last logged encode CRF (the queue shows it for done items)
        [[ "$kind" == pass && "$label" == encode && "$crf" != "-" ]] && ITEM_RUN_CRF[$idx]="$crf"

        [[ "$kind" == pass && "$label" =~ ^(encode|1/2|2/2)$ ]] || continue

        n=${#cs[@]}
        if (( n == 0 )) || [[ "${ci[n-1]}" != "$idx" ]]; then
            cs+=("$ts"); ci+=("$idx"); co+=("$ok"); cin+=("$inp")
        elif [[ "$ok" == 1 ]]; then
            co[n-1]=1
        fi
    done

    [[ -n "$item_crf" ]] && R[crf]="$item_crf"

    # ---- item elapsed
    if [[ -n "$item_start" ]] && (( now >= item_start )); then
        R[item_elapsed]=$(format_hms $(( now - item_start )))
    elif [[ "$pass" == "encode" && "$cur" =~ ^[0-9]+$ && "$speed" =~ ^[0-9.]+$ ]] &&
         awk -v s="$speed" 'BEGIN { exit !(s > 0) }'; then
        # no log header found: encode time so far (ffmpeg speed is the
        # average since the encode started)
        R[item_elapsed]="~$(format_hms "$(awk -v c="$cur" -v s="$speed" 'BEGIN { printf "%.0f", c / s }')") (current encode)"
    fi

    # ---- completed cycles: wall time from the start of one cycle to the
    # start of the next; only cycles whose encode completed and whose
    # source runtime is known
    local sum_media=0 sum_wall=0 cycles=0
    n=${#cs[@]}
    for ((k = 0; k < n; k++)); do
        end=""
        if (( k + 1 < n )); then
            end="${cs[k+1]}"
        elif [[ "${ci[k]}" != "$item" && -n "$item_start" ]] && (( item_start > cs[k] )); then
            end="$item_start"
        fi
        [[ -n "$end" && "${co[k]}" == 1 ]] || continue
        (( end > cs[k] )) || continue
        duration_of "${cin[k]}"
        [[ -n "$DUR_OUT" ]] && (( DUR_OUT > 0 )) || continue
        sum_media=$(( sum_media + DUR_OUT ))
        sum_wall=$(( sum_wall + end - cs[k] ))
        ((cycles++))
    done

    # ---- the current item's remaining wall time
    local cur_rem="" step_note=""
    [[ "$cur" =~ ^[0-9]+$ ]] || cur=""
    if [[ "$item_eta" =~ ^[0-9]+$ ]]; then
        # an ffmpeg run with progress (encode, pass, mux)
        cur_rem="$item_eta"
    elif [[ "$pass" == "encode" || "$pass" == */* ]]; then
        # encoding without a usable speed, or about to start
        if (( cycles > 0 )) && [[ "$duration" =~ ^[0-9.]+$ ]]; then
            cur_rem=$(awk -v d="$duration" -v c="${cur:-0}" -v w="$sum_wall" -v m="$sum_media" \
                'BEGIN { r = (d - c) * w / m; printf "%.0f", (r < 0 ? 0 : r) }')
        fi
    elif (( n > 0 )) && [[ "${ci[n-1]}" == "$item" ]]; then
        # after this item's encode (mux / verify / DV steps): short, not
        # predicted
        cur_rem=0
        step_note="; plus the current step"
    elif (( cycles > 0 )) && [[ "$duration" =~ ^[0-9.]+$ ]]; then
        # this item's encode has not started yet
        cur_rem=$(awk -v d="$duration" -v w="$sum_wall" -v m="$sum_media" 'BEGIN { printf "%.0f", d * w / m }')
    fi

    [[ -n "$cur_rem" ]] || return 0

    # ---- items still to come (this pass): runtimes from the job script
    local rem_items=$(( items - item )) rem_media=0 rem_unknown=0 j rest total

    if (( rem_items <= 0 )); then
        R[total_eta]=$(format_hms "$cur_rem")
        R[total_basis]="last $word of the job${step_note}"
        return 0
    fi

    script_item_inputs "$WORK/${ST[session]:-}.sh"
    for ((j = item + 1; j <= items; j++)); do
        duration_of "${ITEM_IN[$j]:-}"
        if [[ -n "$DUR_OUT" ]]; then
            rem_media=$(( rem_media + DUR_OUT ))
        else
            ((rem_unknown++))
        fi
    done

    if (( cycles > 0 )); then
        # measured throughput (overhead included); a runtime that is
        # unknown counts as an average completed cycle
        rest=$(awk -v rm="$rem_media" -v ru="$rem_unknown" -v w="$sum_wall" -v m="$sum_media" -v c="$cycles" \
            'BEGIN { printf "%.0f", rm * w / m + ru * w / c }')
        R[total_basis]=$(awk -v n="$cycles" -v w="$sum_wall" -v m="$sum_media" -v word="$word" \
            'BEGIN { printf "based on %d completed %s%s at %.3fx overall", n, word, (n == 1 ? "" : "s"), m / w }')
    elif (( rem_unknown == 0 )) && [[ "$speed" =~ ^[0-9.]+$ ]] &&
         awk -v s="$speed" 'BEGIN { exit !(s > 0) }'; then
        rest=$(awk -v rm="$rem_media" -v s="$speed" 'BEGIN { printf "%.0f", rm / s }')
        R[total_basis]="based on the current encode speed (no completed $word yet)"
    else
        return 0
    fi

    total=$(( cur_rem + rest ))
    R[total_eta]=$(format_hms "$total")
    R[total_basis]+="; $rem_items more ${word}$( (( rem_items == 1 )) || echo s) after this one${step_note}"
}

# status_text PASS  ->  what the item is doing:
#   "Encoding"                 single-pass CRF encode
#   "Pass 1/2" / "Pass 2/2"    two-pass encode (older bitrate jobs)
#   "Step: mux" / ...          other steps
status_text() {
    local pass="$1"

    if [[ "$pass" == "encode" ]]; then
        printf 'Encoding'
    elif [[ -z "$pass" || "$pass" == "-" ]]; then
        printf 'Starting'
    elif [[ "$pass" == */* ]]; then
        printf 'Pass %s' "$pass"
    else
        printf 'Step: %s' "$pass"
    fi
}

# ------------------------------------------------------------
# Layout
#
#   c1 — Movie
#   ======================================================================
#
#   CURRENT: <file>
#
#     <tier> | CRF <n>[ (manual)] | <status>
#     Progress:  0.8%   00:00:55 / 01:50:13   0.736x
#     ETA:       <item ETA>    Elapsed: <item elapsed>
#
#   (more than one item:)
#   JOB QUEUE
#   ----------------------------------------------------------------------
#
#     ETA:       <total ETA>    Elapsed: <total elapsed>
#
#     [DONE] 1. <file>      <tier> | CRF <n>
#     [NOW]  2. <file>      <tier> | CRF <n> | <status>
#     [NEXT] 3. <file>      <tier> | CRF <n> (manual)
#     [WAIT] 4. <file>      <tier> | CRF <n>
#
#     Completed: 1
#     Remaining: 2 queued
#   ======================================================================
#
# Queue metadata stays on the file's line when every row fits the
# terminal width (COLUMNS, else tput cols, else 100); otherwise it goes
# on an indented line below each file.
# ------------------------------------------------------------

RULE_WIDE="======================================================================"
RULE_THIN="----------------------------------------------------------------------"

# term_width  ->  columns of the terminal (COLUMNS, tput, else 100)
term_width() {
    local w="${COLUMNS:-}"
    [[ "$w" =~ ^[0-9]+$ ]] || { [[ -t 1 ]] && w=$(tput cols 2>/dev/null); }
    [[ "$w" =~ ^[0-9]+$ ]] && (( w >= 40 )) || w=100
    printf '%s' "$w"
}

# meta_text TIER CRF MANUAL [STATUS]  ->  "Base | CRF 21 (manual) | Encoding"
meta_text() {
    local out="${1:-?}"
    [[ -n "${2:-}" ]] && out+=" | CRF $2$( [[ "${3:-}" == 1 ]] && echo " (manual)")"
    [[ -n "${4:-}" ]] && out+=" | $4"
    printf '%s' "$out"
}

# script_item_meta SCRIPT  ->  fills ITEM_IN / ITEM_TIER / ITEM_CRF /
# ITEM_MANUAL / ITEM_COPY per item index from the job script's item_begin
# and item_expect lines (planned values; none for old job formats)
script_item_meta() {
    local line idx="" w crf
    local -a words

    ITEM_IN=() ITEM_TIER=() ITEM_CRF=() ITEM_MANUAL=() ITEM_COPY=()
    [[ -f "$1" ]] || return 0

    while IFS= read -r line; do
        if [[ "$line" =~ (^|[[:space:]])item_begin[[:space:]]+([0-9]+)[[:space:]] ]]; then
            idx="${BASH_REMATCH[2]}"
            [[ -z "${ITEM_IN[$idx]+x}" ]] || { idx=""; continue; }
            mapfile -t words < <(xargs -n 1 2>/dev/null <<< "${line#*item_begin }")
            ITEM_IN[$idx]="${words[1]:-}"
            ITEM_TIER[$idx]="${words[3]:-}"
        elif [[ -n "$idx" && "$line" == *item_expect* ]]; then
            crf=""
            [[ "$line" =~ [[:space:]]crf=([0-9.]+) ]] && crf="${BASH_REMATCH[1]}"
            ITEM_CRF[$idx]="$crf"
            [[ "$line" == *" down_mode=manual"* ]] && ITEM_MANUAL[$idx]=1
            [[ "$line" == *" mode=copy"* ]] && ITEM_COPY[$idx]=1
            idx=""
        fi
    done < <(grep -E 'item_(begin|expect) ' "$1" 2>/dev/null)
}

# print_header  ->  "c1 — Movie" and the wide rule
print_header() {
    printf '%s — %s\n' "${R[session]}" "${R[type]}"
    echo "$RULE_WIDE"
    echo
}

# print_current  ->  the CURRENT block from R[...]: name tier crf manual
# status pct enc total speed item_eta item_elapsed logs note_crf
print_current() {
    echo "CURRENT: ${R[name]:-?}"
    echo
    echo "  $(meta_text "${R[tier]:-?}" "${R[crf]:-}" "${R[manual]:-}" "${R[status]:-?}")"
    [[ -n "${R[pct]:-}" ]] &&
        printf '  %-11s%s   %s / %s   %s\n' "Progress:" "${R[pct]}" "${R[enc]}" "${R[total]}" "${R[speed]}"
    printf '  %-11s%s    Elapsed: %s\n' "ETA:" "${R[item_eta]:-Unknown}" "${R[item_elapsed]:-Unknown}"
    [[ -n "${R[item_label]:-}" ]] && printf '  %-11s%s\n' "Item:" "${R[item_label]}"
    [[ -n "${R[logs]:-}" ]] && printf '  %-11s%s\n' "Logs:" "${R[logs]}"
    return 0
}

# print_queue CURRENT ITEMS  ->  the JOB QUEUE block (whole job, the
# current item included) from ITEM_* / ITEM_RUN_CRF and R[...]
print_queue() {
    local cur="$1" items="$2" j tag name meta pre w namew=0 metaw=0 inline=1 dw done
    local -a names=() metas=() tags=()

    dw=${#items}
    for ((j = 1; j <= items; j++)); do
        if (( j < cur )); then
            tag="[DONE]"
        elif (( j == cur )); then
            tag="[NOW]"
        elif (( j == cur + 1 )); then
            tag="[NEXT]"
        else
            tag="[WAIT]"
        fi
        name="${ITEM_IN[$j]:-}"
        name="${name##*/}"
        # a name the job script quoted as $'...' (non-UTF-8 locale) comes
        # out of xargs with octal escapes: decode them for display
        [[ "$name" =~ \\[0-7]{3} ]] && name=$(printf '%b' "${name//\\/\\0}")
        (( j == cur )) && name="${R[name]:-$name}"
        [[ -n "$name" ]] || name="?"
        if (( j == cur )); then
            meta=$(meta_text "${R[tier]:-?}" "${R[crf]:-}" "${R[manual]:-}" "${R[status]:-}")
        elif [[ -n "${ITEM_COPY[$j]:-}" ]]; then
            meta=$(meta_text "${ITEM_TIER[$j]:-?}" "" "" "source video kept")
        elif (( j < cur )) && [[ -n "${ITEM_RUN_CRF[$j]:-}" ]]; then
            meta=$(meta_text "${ITEM_TIER[$j]:-?}" "${ITEM_RUN_CRF[$j]}" "${ITEM_MANUAL[$j]:-}")
        else
            meta=$(meta_text "${ITEM_TIER[$j]:-?}" "${ITEM_CRF[$j]:-}" "${ITEM_MANUAL[$j]:-}")
        fi
        tags+=("$tag"); names+=("$name"); metas+=("$meta")
        (( ${#name} > namew )) && namew=${#name}
        (( ${#meta} > metaw )) && metaw=${#meta}
    done

    # "  [NEXT] 12. " + name + 2 spaces + meta must fit the terminal
    pre=$(( 2 + 6 + 1 + dw + 2 ))
    w=$(term_width)
    (( pre + namew + 2 + metaw <= w )) || inline=0

    echo
    echo
    echo "JOB QUEUE"
    echo "$RULE_THIN"
    echo
    printf '  %-11s%s    Elapsed: %s\n' "ETA:" "${R[total_eta]:-Unknown}" "${R[total_elapsed]:-Unknown}"
    echo
    for ((j = 1; j <= items; j++)); do
        if (( inline )); then
            # padded by characters (printf pads by bytes: a multibyte name
            # would shift the metadata column)
            printf '  %-6s %*s. %s%*s  %s\n' "${tags[j-1]}" "$dw" "$j" "${names[j-1]}" \
                "$(( namew - ${#names[j-1]} ))" "" "${metas[j-1]}"
        else
            printf '  %-6s %*s. %s\n' "${tags[j-1]}" "$dw" "$j" "${names[j-1]}"
            printf '%*s%s\n' "$pre" "" "${metas[j-1]}"
            (( j < items )) && echo
        fi
    done
    echo
    done=$(( cur - 1 ))
    (( done < 0 )) && done=0
    printf '  Completed: %s%s\n' "$done" "$( (( ${ST[failed]:-0} > 0 )) && echo " (${ST[failed]} failed)")"
    printf '  Remaining: %s queued\n' "$(( items - cur > 0 ? items - cur : 0 ))"
    [[ -n "${R[note_crf]:-}" ]] && echo "  Note: CRF retries/tests not yet started are excluded"
    return 0
}

# print_job [CURRENT ITEMS]  ->  one job: header, CURRENT, and with more
# than one item the JOB QUEUE (ITEM_* filled by script_item_meta)
print_job() {
    local cur="${1:-0}" items="${2:-0}"

    print_header
    print_current
    if [[ "$items" =~ ^[0-9]+$ && "$cur" =~ ^[0-9]+$ ]] && (( items > 1 && cur >= 1 )); then
        print_queue "$cur" "$items"
    else
        [[ -n "${R[note_crf]:-}" ]] && echo "  Note: CRF retries/tests not yet started are excluded"
        echo
    fi
    echo "$RULE_WIDE"
    echo
}

# print_ended  ->  a job that is over while its session still waits
print_ended() {
    print_header
    echo "${R[status]:-?}"
    [[ -n "${R[logs]:-}" ]] && printf '  %-11s%s\n' "Logs:" "${R[logs]}"
    printf '  %-11s%s\n' "Elapsed:" "${R[total_elapsed]:-Unknown}"
    echo
    echo "$RULE_WIDE"
    echo
}

# progress_fields CURRENT_SEC DURATION SPEED  ->  "percent eta"
progress_fields() {
    awk -v c="$1" -v t="$2" -v s="$3" 'BEGIN {
        if (c !~ /^[0-9.]+$/ || t !~ /^[0-9.]+$/ || t <= 0) { print "- -"; exit }
        pct = c / t * 100
        if (pct > 100) pct = 100
        if (s ~ /^[0-9.]+$/ && s > 0) {
            r = (t - c) / s
            if (r < 0) r = 0
            printf "%.1f%% %.0f\n", pct, r
        } else {
            printf "%.1f%% -\n", pct
        }
    }'
}

# item_header TYPE ITEM  ->  "Episode 4/6" ("-" for an unknown index)
item_header() {
    local i="${2:-}"
    [[ -z "$i" || "$i" == 0/* ]] && i="-/${i#*/}"
    printf '%s %s' "$(item_word "$1")" "$i"
}

declare -A ST
declare -A LIVE
declare -A R
declare -A DUR
declare -A ITEM_IN ITEM_TIER ITEM_CRF ITEM_MANUAL ITEM_COPY ITEM_RUN_CRF
DUR_OUT=""
shown=0

mapfile -t sessions < <(
    tmux list-sessions -F '#{session_name} #{session_created}' 2>/dev/null |
    awk '$1 ~ /^(c|series|a)[0-9]+$/' |
    sort -V
)

echo

for entry in "${sessions[@]+"${sessions[@]}"}"; do
    session="${entry%% *}"
    created="${entry##* }"
    type=$(job_type_for "$session")
    LIVE["$session"]=1
    now=$(date +%s)

    R=()
    R[session]="$session"
    R[type]=$(type_label "$type")

    state_file="$WORK/$session.state"
    script="$WORK/$session.sh"

    # --------------------------------------------------------
    # Current job format (state file)
    # --------------------------------------------------------

    if [[ -f "$state_file" ]] &&
       [[ ! -f "$script" || ! "$state_file" -ot "$script" ]]; then

        read_state "$state_file"

        R[name]="${ST[name]:-?}"
        R[tier]="${ST[tier]:-?}"
        R[crf]="${ST[crf]:-}"
        pass="${ST[pass]:-}"
        duration="${ST[duration]:-}"
        status="${ST[status]:-?}"

        started="${ST[started]:-}"
        [[ "$started" =~ ^[0-9]+$ ]] || started="$created"
        if [[ "$started" =~ ^[0-9]+$ ]]; then
            R[total_elapsed]=$(format_hms $(( now - started )))
        fi

        case "$status" in
            failed|finished)
                # the job is over (the session waits for Enter): elapsed up
                # to its last state update
                R[ended]=1
                R[crf]=""
                if [[ "$started" =~ ^[0-9]+$ && "${ST[updated]:-}" =~ ^[0-9]+$ ]]; then
                    R[total_elapsed]=$(format_hms $(( ${ST[updated]} - started )))
                fi
                if [[ "$status" == failed ]]; then
                    R[status]="FINISHED WITH ERRORS: ${ST[ok]:-0} ok, ${ST[failed]:-0} failed (session waits for Enter)"
                    R[logs]="${ST[log_dir]:-?}"
                else
                    R[status]="Finished: ${ST[ok]:-0} ok"
                fi
                print_ended
                ((shown++))
                continue
                ;;
        esac

        read -r cur speed prog <<< "$(progress_values "${ST[progress]:-$WORK/$session.progress}")"

        if [[ -z "$pass" || "$cur" == "-" ]]; then
            case "$pass" in
                "")     R[status]="Starting" ;;
                encode) R[status]="Starting encode" ;;
                */*)    R[status]="Starting $(status_text "$pass")" ;;
                *)      R[status]=$(status_text "$pass") ;;
            esac
            item_eta=""
            cur="-"
        else
            R[status]=$(status_text "$pass")
            read -r pct item_eta <<< "$(progress_fields "$cur" "$duration" "$speed")"
            if [[ "$pct" != "-" ]]; then
                R[pct]="$pct"
                R[enc]=$(format_hms "$cur")
                R[total]=$(format_hms "$duration")
                R[speed]="${speed}x"
                [[ "$speed" == "-" ]] && R[speed]="Unknown"
            fi
            [[ "$item_eta" =~ ^[0-9]+$ ]] && R[item_eta]=$(format_hms "$item_eta")
        fi

        (( ${ST[failed]:-0} > 0 )) && R[status]+=" (${ST[failed]} failed so far)"

        job_estimates "$now" "$cur" "$speed" "${item_eta:-}"

        # CRF only means something for a CRF encode
        [[ "${ST[mode]:-}" == "crf" ]] || R[crf]=""

        # High / Base / Quality may re-encode after the post-encode CRF
        # check (movie CRF - 1 test, series season retry / test pass)
        [[ "${ST[mode]:-}" == "crf" && "${R[tier]}" != "Custom" && "${R[total_eta]}" != "Unknown" ]] &&
            R[note_crf]=1

        # the whole job's items (queue) from the job script
        script_item_meta "$script"
        R[manual]="${ITEM_MANUAL[${ST[item]:-0}]:-}"

        print_job "${ST[item]:-0}" "${ST[items]:-0}"
        ((shown++))
        continue
    fi

    # --------------------------------------------------------
    # Legacy jobs: parse pane history + job script
    # --------------------------------------------------------

    pane=$(tmux capture-pane -p -J -S - -t "=$session:" 2>/dev/null || true)

    input=""
    name="Unknown"
    tier=$(grep -oE 'Tier:[[:space:]]*[^"]+' <<< "$pane" | tail -n 1 | sed -E 's/^Tier:[[:space:]]*//')
    pass=$(grep -oE 'PASS [0-9]/[0-9]' <<< "$pane" | tail -n 1 | cut -d' ' -f2)
    item="-"

    case "$type" in
        movie)
            input=$(grep -E '^Encoding: ' <<< "$pane" | tail -n 1 | sed -E 's/^Encoding: //')

            if [[ -f "$script" ]]; then
                mapfile -t all < <(script_inputs "$script")
                for i in "${!all[@]}"; do
                    if [[ "${all[$i]}" == "$input" ]]; then
                        item="$((i + 1))/${#all[@]}"
                    fi
                done
            fi
            ;;
        series)
            item=$(grep -oE 'Episode [0-9]+/[0-9]+' <<< "$pane" | tail -n 1 | cut -d' ' -f2)
            file=$(grep -E '^File: ' <<< "$pane" | tail -n 1 | sed -E 's/^File: //')

            if [[ -n "$file" && -f "$script" ]]; then
                while IFS= read -r p; do
                    if [[ "$(basename "$p")" == "$file" ]]; then
                        input="$p"
                        break
                    fi
                done < <(script_inputs "$script")
            fi

            [[ -z "$input" && -n "$file" ]] && name="$file"
            ;;
        audio)
            if [[ -f "$script" ]]; then
                input=$(first_word "$(grep -m1 -E '^IN=' "$script" | sed -E 's/^IN=//')")
            fi
            pass="mux"
            tier="audio"
            item="1/1"
            ;;
    esac

    [[ -n "$input" ]] && name=$(basename "$input")
    [[ -n "$tier" ]] || tier="?"
    [[ -n "$item" ]] || item="-"

    R[item_label]=$(item_header "$type" "$item")
    R[name]="$name"
    R[tier]="$tier"
    [[ "$created" =~ ^[0-9]+$ ]] && R[total_elapsed]=$(format_hms $(( now - created )))
    # old job format: no item logs / runtimes to base these on
    R[item_elapsed]="Unknown"
    R[total_eta]="Unknown"
    R[total_basis]="old job format"

    cur=$(grep -oE 'time=-?[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]+' <<< "$pane" | tail -n 1 | cut -d= -f2)
    speed=$(grep -oE 'speed=[ ]*[0-9.]+x' <<< "$pane" | tail -n 1 | sed -E 's/speed=[ ]*//; s/x$//')

    duration=""
    if [[ -n "$input" && -f "$input" ]]; then
        duration=$(get_duration "$input" 2>/dev/null || true)
    fi

    if [[ -z "$cur" || "$cur" == -* ]]; then
        if [[ -z "$pass" ]]; then
            R[status]="Starting (old job format)"
        else
            R[status]="Starting $(status_text "$pass") (old job format)"
        fi
    else
        IFS=: read -r h m s <<< "$cur"
        cur_sec=$(awk -v h="$h" -v m="$m" -v s="$s" 'BEGIN { printf "%.0f", h*3600 + m*60 + s }')
        read -r pct eta <<< "$(progress_fields "$cur_sec" "$duration" "${speed:--}")"
        R[status]="$(status_text "${pass:--}") (old job format)"
        [[ -z "$pass" ]] && R[status]="Encoding (old job format)"
        if [[ "$pct" != "-" ]]; then
            R[pct]="$pct"
            R[enc]=$(format_hms "$cur_sec")
            R[total]=$(format_hms "$duration")
            R[speed]="${speed:-?}x"
            [[ -z "$speed" ]] && R[speed]="Unknown"
        fi
        if [[ "$eta" =~ ^[0-9]+$ ]]; then
            R[item_eta]=$(format_hms "$eta")
            # a single-item job: the item is the whole job
            if [[ "$item" == 1/1 ]]; then
                R[total_eta]="${R[item_eta]}"
                R[total_basis]="last item of the job"
            fi
        fi
    fi

    print_job
    ((shown++))
done

if (( shown == 0 )); then
    echo "No compression tmux sessions running."
    echo
fi

# ------------------------------------------------------------
# Recently ended jobs (state file left behind, session gone)
# ------------------------------------------------------------

ended=0

while IFS= read -r -d '' state_file; do
    session=$(basename "$state_file" .state)
    [[ -n "${LIVE[$session]+x}" ]] && continue
    [[ -n "$(job_type_for "$session")" ]] || continue

    read_state "$state_file"

    if (( ended == 0 )); then
        echo "Recently ended (last ${RECENT_HOURS}h):"
        echo
    fi
    ((ended++))

    when=$(date -d "@${ST[updated]:-0}" '+%F %H:%M' 2>/dev/null || echo "?")

    case "${ST[status]:-}" in
        finished)    result="finished: ${ST[ok]:-0}/${ST[items]:-?} ok" ;;
        failed)      result="FINISHED WITH ERRORS: ${ST[ok]:-0} ok, ${ST[failed]:-0} failed" ;;
        interrupted) result="INTERRUPTED at item ${ST[item]:-?}/${ST[items]:-?} (${ST[name]:-?})" ;;
        *)           result="STOPPED UNEXPECTEDLY at item ${ST[item]:-?}/${ST[items]:-?} (${ST[name]:-?})" ;;
    esac

    printf '%-9s %-7s %s  %s\n' "$session" "${ST[type]:-?}" "$when" "$result"

    if [[ "${ST[status]:-}" != "finished" && -d "${ST[log_dir]:-/nonexistent}" ]]; then
        printf '    Logs: %s\n' "${ST[log_dir]}"
    fi
done < <(
    find "$WORK" -maxdepth 1 -type f -name '*.state' \
        -mmin "-$((RECENT_HOURS * 60))" -print0 2>/dev/null |
    sort -zV
)

(( ended > 0 )) && echo
exit 0
